	c.Set("foo", "bar")
	got, ok := c.Get("foo")
	if !ok || got != "bar" {
		t.Fatalf("Get(foo) = %q, %v; want bar, true", got, ok)
	}
}

func TestKVCache_GetMissing(t *testing.T) {
	c := newTestCache()
	if _, ok := c.Get("nope"); ok {
		t.Fatal("expected missing key")
	}
}

